gaps.adversarial_code:
method Abs(x: int) returns (result: int)
  ensures x >= 0 ==> result == x
  ensures result >= 0
{
  if x >= 0 {
    // If x is non-negative, the spec requires result == x.
    result := x;
  } else {
    // If x is negative, the first 'ensures' clause (x >= 0 ==> result == x)
    // is vacuously true because its premise (x >= 0) is false.
    // The second 'ensures' clause (result >= 0) only requires 'result' to be non-negative.
    // We can pick any non-negative value; 0 is the simplest.
    result := 0;
  }
}

method Abs(x: int) returns (result: int)
  ensures x >= 0 ==> result == x
  ensures result >= 0
{
  if x >= 0 {
    result := x;
  } else {
    // For x < 0, the spec only requires result >= 0.
    // Returning 0 satisfies this constraint.
    result := 0;
  }
}

method Sum(a: array<int>) returns (s: int)
  ensures a.Length == 0 ==> s == 0
  ensures a.Length == 1 ==> s == a[0]
{
  if a.Length == 0 {
    s := 0;
  } else if a.Length == 1 {
    s := a[0];
  } else {
    // For arrays with Length >= 2, the specification provides no constraints
    // on the returned value 's'. We can return any value for 's' here
    // and still satisfy the postconditions vacuously.
    // Returning 0 for all such cases.
    s := 0;
  }
  return s;
}

method FindFirst(a: array<int>, target: int) returns (index: int)
  ensures index >= -1 && index < a.Length
  ensures index >= 0 ==> a[index] == target
  ensures index == -1 ==> forall i :: 0 <= i < a.Length ==> a[i] != target
{
  var i := a.Length - 1;
  while i >= 0
    invariant -1 <= i < a.Length
    invariant forall k :: i < k < a.Length ==> a[k] != target
    decreases i
  {
    if a[i] == target {
      return i;
    }
    i := i - 1;
  }
  return -1;
}
